/**
 * Form indexes of the Hebrew adapter: attested written forms → the analyses a source gives them.
 *
 * Two indexes exist, both GENERATED by scripts (never hand-edited):
 *   oshb-tanakh        every word of the Tanakh as the Open Scriptures Hebrew Bible morphology reads it, aligned to the MAM
 *                      text (scripts/he-build-biblical.mts, from the Biblia app's data). A reading here is a scholarly
 *                      source's reading of that very word in the Bible: period he-bib (or arc-bib for the Aramaic chapters).
 *   kaikki-he-tables   the inflection tables of the Wiktionary (kaikki.org) Hebrew entries, period he-mod
 *                      (scripts/he-build-modern.mts).
 *
 * A compact CORE of the Tanakh index (the closed classes and the commonest lemmas) is compiled into the adapter
 * (generated/biblical-core.ts) so that analysis works with nothing loaded. The full indexes are JSON assets
 * (public/lexicon/he/*.json, git-ignored, rebuilt by the scripts) that a host installs with `installHebrewIndex` when the
 * language is loaded; until then the core answers and the adapter says what it does not have.
 *
 * Keys: `pointed(form)` from text.ts — NFC, cantillation and meteg removed, vowels and dagesh kept. `consonantal` maps a
 * skeleton to the pointed keys that have it, so an unpointed selection can reach the pointed Biblical forms.
 */
import { consonantal } from './text';

/** [headword as the source prints it, short gloss, part of speech (UPOS), token count in the source, transliteration?] */
export type HeLemmaRow = [headword: string, gloss: string, pos: string, count: number, translit?: string];
/**
 * One analysis of one form. `lemma` is the lemma id with its prefix chain as the source gives it ("c/d/776" = וְ + הַ + 776);
 * `code` is the source's own code (an OSHB morphology code such as "HC/Td/Ncbsa", or a kaikki tag list "past|third-person|masculine|singular");
 * `count` is how often the source reads the form this way; `seg` the letters per morpheme ("1/1/3") when the source segments it.
 */
export type HeFormRow = [lemma: string, code: string, count: number, seg?: string];

export interface HebrewFormIndex {
  schema: 1;
  id: 'oshb-tanakh' | 'kaikki-he-tables' | string;
  /** How `HeFormRow.code` is to be read. */
  codes: 'oshb' | 'kaikki-tags';
  /** The period variety every reading of this index belongs to (a row may override it: see `aramaic`). */
  period: 'he-bib' | 'he-mod';
  /** A SHARD of a larger index (scripts/lexicon-shard.mts): the prefix of the consonants its keys share; shards of one id are installed side by side. */
  shard?: string;
  source: { label: string; licence: string; url: string; retrieved?: string; note?: string };
  built: string;
  lemmas: Record<string, HeLemmaRow>;
  forms: Record<string, HeFormRow[]>;
  /** skeleton → pointed keys (only listed where at least one pointed key differs from the skeleton) */
  consonantal: Record<string, string[]>;
  /** For the Tanakh: lemma ids whose readings are Biblical Aramaic (the code starts with "A"); they are tagged arc-bib. */
  stats?: Record<string, number>;
}

export interface HeIndexHit {
  index: HebrewFormIndex;
  /** The pointed key that matched (for an unpointed query, one of the pointed forms with that skeleton). */
  key: string;
  row: HeFormRow;
  /** True when the query was unpointed and the key was reached through the consonantal map. */
  viaConsonantal: boolean;
}

const INSTALLED = new Map<string, HebrewFormIndex>();
const storeKey = (id: string, shard?: string): string => (shard ? `${id}#${shard}` : id);

/** Install (or replace) an index, or one shard of one (keyed by id and shard, so the shards of an id sit side by side). The core index is installed by the adapter module itself; a host adds the full assets. */
export function installHebrewIndex(idx: HebrewFormIndex): void {
  INSTALLED.set(storeKey(idx.id, idx.shard), idx);
}
export function uninstallHebrewIndex(id: string, shard?: string): boolean { return INSTALLED.delete(storeKey(id, shard)); }
export function installedHebrewIndexes(): HebrewFormIndex[] {
  return [...INSTALLED.values()];
}
/** For tests: forgets every installed index (or shard) for which `keep(id, shard)` is not true. */
export function resetHebrewIndexes(keep?: (id: string, shard?: string) => boolean): void {
  for (const [k, idx] of [...INSTALLED.entries()]) if (!keep?.(idx.id, idx.shard)) INSTALLED.delete(k);
}

/**
 * Readings of a pointed key across the installed indexes, most frequent first. When `pointedKey` has no points, the
 * consonantal map of each index is consulted as well, and every pointed form with that skeleton contributes its rows.
 */
export function lookupHebrewForm(pointedKey: string): HeIndexHit[] {
  const out: HeIndexHit[] = [];
  const skel = consonantal(pointedKey);
  const unpointed = skel === pointedKey;
  for (const index of INSTALLED.values()) {
    const direct = index.forms[pointedKey];
    if (direct) for (const row of direct) out.push({ index, key: pointedKey, row, viaConsonantal: false });
    if (unpointed) {
      for (const key of index.consonantal[skel] ?? []) {
        if (key === pointedKey) continue;
        for (const row of index.forms[key] ?? []) out.push({ index, key, row, viaConsonantal: true });
      }
    }
  }
  return out.sort((a, b) => b.row[2] - a.row[2]);
}

/** The lemma row of a lemma id (without its prefix chain) in the index that holds it. */
export function lookupHebrewLemma(lemmaId: string, index?: HebrewFormIndex): HeLemmaRow | undefined {
  if (index) return index.lemmas[lemmaId];
  for (const idx of INSTALLED.values()) { const r = idx.lemmas[lemmaId]; if (r) return r; }
  return undefined;
}

/** The lemma id proper, after the prefix chain ("c/d/776" → "776"; "1254 a" stays). */
export const lemmaStem = (lemma: string): string => lemma.split('/').pop()!.replace(/\+$/, '');
/** The prefix codes before the lemma id ("c/d/776" → ["c", "d"]). */
export const lemmaPrefixes = (lemma: string): string[] => lemma.split('/').slice(0, -1);
